  "headline": "Droperidol is not on FDA's shortage list as of 2026-10-21; current supply at Corvale East covers 9.1 days and Corvale General covers 13.2 days",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include droperidol as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 62 vials of droperidol 2.5 mg/mL, 2 mL with a daily use of 6.8 vials, providing 9.1 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 113 vials of the same presentation with a daily use of 8.5 vials, providing 13.2 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The product label identifies Hikma Farmaceutica (Portugal), S.A. as the manufacturing plant (FEI 3002807173).",
      "cites": ["E12"]
    },
    {
      "text": "That plant received a Warning Letter on 2014-10-21 and an OAI inspection classification on 2014-03-28, but its most recent inspections in 2023 were classified VAI.",
      "cites": ["E11", "E5", "E9", "E10"]
    },
    {
      "text": "The recommended purchasing option is to buy from American Regent, Inc., whose plant was last inspected VAI on 2024-04-24.",
      "cites": ["D4"]
    }
  ]
}
